 SET character_set_client = utf8mb4 ;
CREATE TABLE `t_species` (
  `species_id` int(11) NOT NULL COMMENT '主键',
  `c_name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '物种中文名称',
  `latin_name` varchar(40) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '物种拉丁正式名',
  `category_id` int(11) NOT NULL COMMENT '物种所属类别',
  `brief_introduction` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '物种简介',
  `detail_introduction` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '物种详情',
  `recommend` int(1) DEFAULT NULL COMMENT '是否推荐，0：不推荐；1：推荐；每次24时刷新生成推荐内容',
  `level` int(1) DEFAULT NULL COMMENT '保护级别：1：国1；2国2；3三有；0：非保护',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`species_id`) USING BTREE
