INSERT INTO `t_species` VALUES (1,'鸭嘴兽','Ornithorhynchus anatinus',182,'鸭嘴兽（学名：Ornithorhynchus anatinus；英语：Platypus，偶称Duck-billed platypus）是少有的卵生哺乳类动物，用肺部呼吸，栖息地在澳大利亚东部地区和塔斯马尼亚州，是原兽亚纲单孔目鸭嘴兽科鸭嘴兽属（Ornithorhynchus）的唯一一种动物。',NULL,1,NULL,NULL,NULL),(2,'澳洲针鼹','Tachyglossus aculeatus',183,NULL,NULL,1,NULL,NULL,NULL),(3,'阿滕伯勒长喙针鼹','Zaglossus attenboroughi',184,NULL,NULL,1,NULL,NULL,NULL),(4,'大长吻针鼹','Zaglossus bartoni',184,NULL,NULL,1,NULL,NULL,NULL),(5,'长吻针鼹','Zaglossus brujinii',184,NULL,NULL,1,NULL,NULL,NULL),(6,'弗因博斯金鼹','Amblysomus corriae',185,NULL,NULL,1,NULL,NULL,NULL),(7,'何腾托金鼹','Amblysomus hottentotus',185,NULL,NULL,1,NULL,NULL,NULL),(8,'马氏金鼹','Amblysomus marleyi',185,NULL,NULL,1,NULL,NULL,NULL),(9,'硕金鼹','Amblysomus robustus',185,NULL,NULL,1,NULL,NULL,NULL),(10,'高原金鼹','Amblysomus septentrionalis',185,NULL,NULL,1,NULL,NULL,NULL),(11,'刚果黄毛鼹','Calcochloris leucorhinus',186,NULL,NULL,1,NULL,NULL,NULL),(12,'黄毛鼹','Calcochloris obtusirostris',186,NULL,NULL,1,NULL,NULL,NULL),(13,'索马里黄毛鼹','Calcochloris tytonis',186,NULL,NULL,1,NULL,NULL,NULL),(14,'冈氏金鼹','Neamblysomus gunningi',187,NULL,NULL,1,NULL,NULL,NULL),(15,'朱氏金鼹','Neamblysomus julianae',187,NULL,NULL,1,NULL,NULL,NULL),(16,'亚伦斯金鼹','Carpitalpa arendsi',188,NULL,NULL,1,NULL,NULL,NULL),(17,'迪氏绿鼹','Chlorotalpa duthieae',189,NULL,NULL,1,NULL,NULL,NULL),(18,'斯氏绿鼹','Chlorotalpa sclateri',189,NULL,NULL,1,NULL,NULL,NULL),(19,'开普金毛鼹','Chrysochloris asiatica',190,NULL,NULL,1,NULL,NULL,NULL),(20,'斯氏金毛鼹','Chrysochloris stuhlmanni',190,NULL,NULL,1,NULL,NULL,NULL),(21,'维氏金毛鼹','Chrysochloris visagiei',190,NULL,NULL,1,NULL,NULL,NULL),(22,'巨金鼹','Chrysospalax trevelyani',191,NULL,NULL,1,NULL,NULL,NULL),(23,'粗毛金鼹','Chrysospalax villosus',191,NULL,NULL,1,NULL,NULL,NULL),(24,'温氏金鼹','Cryptochloris wintoni',192,NULL,NULL,1,NULL,NULL,NULL),(25,'范齐尔金鼹','Cryptochloris zyli',192,NULL,NULL,1,NULL,NULL,NULL),(26,'荒漠鼹','Eremitalpa granti',193,NULL,NULL,1,NULL,NULL,NULL),(27,'大耳马岛猬','Geogale aurita',194,NULL,NULL,1,NULL,NULL,NULL),(28,'蹼足猬','Limnogale 