DROP TABLE IF EXISTS `t_works`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `t_works` (
  `works_id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL COMMENT '用户id',
  `user_name` int(11) DEFAULT NULL,
  `species_id` int(11) DEFAULT NULL COMMENT '物种id',
  `image_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '摄影作品路径',
  `works_author` int(11) DEFAULT NULL,
  `works_description` int(11) DEFAULT NULL,
  `is_public` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '是否公开：1：公开；0：不公开',
  `works_commentcount` int(11) DEFAULT NULL COMMENT '评论数量',
  `works_viewcount` int(11) DEFAULT NULL COMMENT '播放量',
  `works_likecount` int(11) DEFAULT NULL COMMENT '点赞数量',
  `works_time` int(11) DEFAULT NULL,
  `works_update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`works_id`) USING BTREE,
  KEY `species_id` (`species_id`) USING BTREE,
  KEY `t_works_ibfk_2` (`user_id`) USING BTREE,
  CONSTRAINT `t_works_ibfk_1` FOREIGN KEY (`species_id`) REFERENCES `species_image` (`image_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `t_works_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `t_user` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
